/** The directory a shell command runs git in, from `git -C <dir>` or a leading `cd <dir> &&`. */
export const gitDir = (command: string): string | undefined => {
  const word =
    /\bgit\s+-C\s+("[^"]+"|'[^']+'|\S+)/.exec(command)?.[1] ??
    /^\s*cd\s+("[^"]+"|'[^']+'|\S+)\s*&&/.exec(command)?.[1];

  return word?.replace(/^["']|["']$/g, "");
};

files.hooks/opens-or-edits-pr.ts:
/** Whether a shell command runs gh pr create or gh pr edit. */
export const opensOrEditsPr = (command: string): boolean =>
  /\bgh\s+pr\s+(create|edit)\b/.test(command);

files.hooks/pr-url.ts:
const PR_URL = /https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/pull\/\d+/;

/** The first GitHub pull request URL in a text, as gh pr create and gh pr edit print it. */
export const prUrl = (text: string): string | undefined => PR_URL.exec(text)?.[0];

