import { carriesAttribution } from "./carries-attribution";

/** The text with every line that credits Claude removed, and the blank runs that leaves collapsed. */
export const withoutAttribution = (text: string): string =>
  text
    .split("\n")
    .filter((line) => !carriesAttribution(line))
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trimEnd();

files.hooks/carries-attribution.ts:
const ATTRIBUTION = [
  /^\s*co-authored-by:.*\b(claude|anthropic)\b/i,
  /^\s*claude-session:/i,
  /generated with \[?claude/i,
  /🤖/u,
  /claude\.ai\/code/i,
  /\bsession_[A-Za-z0-9]{6,}/,
];

/** Whether a line credits Claude: a co-author trailer, a session link or the generated-with footer. */
export const carriesAttribution = (line: string): boolean =>
  ATTRIBUTION.some((pattern) => pattern.test(line));

